export const businessRules = [
 {id:'BR-001',name:'Sign-in is not attendance',domain:'attendance',invariant:'Present requires successful clock-in and clock-out.'},
 {id:'BR-002',name:'Actual print material use',domain:'printing',invariant:'Complete requires actual material usage and QC evidence.'},
 {id:'BR-003',name:'Actual bakery yield',domain:'bakery',invariant:'Completion requires nonnegative actual yield; expected yield is never substituted.'},
 {id:'BR-004',name:'Loaf and settlement separation',domain:'bakery-accountability',invariant:'Accounted money may include an outstanding obligation; the frontend cannot present money received, issue a receipt or close financially without an authoritative received-only settlement record.'},
 {id:'BR-005',name:'Proof of delivery',domain:'logistics',invariant:'A trip cannot be delivered or closed without POD evidence.'},
 {id:'BR-006',name:'Maker-checker decisions',domain:'shared',invariant:'Maker cannot approve their own controlled request; decision reason is required.'},
 {id:'BR-007',name:'Balanced journal',domain:'finance',invariant:'Posting requires finite equal debit and credit values in an open period.'},
 {id:'BR-008',name:'Commitment recognition',domain:'purchase-orders',invariant:'Approval alone creates no active commitment. Ordered and partial-received balances do.'},
 {id:'BR-009',name:'Receipt accountability',domain:'goods-receipts',invariant:'Accepted plus rejected quantity equals delivered quantity.'},
 {id:'BR-010',name:'Human publication approval',domain:'social',invariant:'Human approval and explicit Publish permission precede any simulated publication.'},
 {id:'BR-011',name:'Zero disclosure',domain:'security',invariant:'No assignment means no disclosure; missing and unauthorized resources share a neutral result.'},
 {id:'BR-012',name:'Specialized permission',domain:'security',invariant:'Export, Pay, Publish and other specialized actions are explicit, never implied by a level.'},
 {id:'BR-013',name:'Config safety',domain:'builders',invariant:'No arbitrary SQL/JavaScript; protected business invariants cannot be disabled.'},
 {id:'BR-014',name:'Stock custody',domain:'stock-transfers',invariant:'Transfer closure requires received quantity equal to dispatched quantity.'},
 {id:'BR-015',name:'Borrowed stock',domain:'stock-borrowing',invariant:'Closure requires the full issued quantity returned.'},
 {id:'BR-016',name:'Payroll readiness',domain:'payroll',invariant:'Net pay, bank validation, statutory configuration and approval are separate gates.'},
 {id:'BR-017',name:'Authoritative communication events',domain:'customer-communications',invariant:'Opening a screen never sends a message; sends require an authorized event or an approved manual flow with idempotency, consent and audit.'},
 {id:'BR-018',name:'Human communication approval',domain:'customer-communications',invariant:'AI may draft, but a manually initiated customer communication follows Generate, Preview, Edit, Approve, Send.'},
 {id:'BR-019',name:'Server-side provider authority',domain:'integrations',invariant:'Provider credentials, signatures, webhook verification and retries belong in production server-side adapters, never the frontend.'},
 {id:'BR-020',name:'Verified payment activation',domain:'payment-verification',invariant:'A bank notification alone cannot activate service; verified provider event, match, authoritative payment state and applicable business rule are all required.'},
 {id:'BR-021',name:'Transfer separation of duties',domain:'transfers',invariant:'Create, approve, execute and reconcile are separate grants; a maker cannot approve their own controlled transfer.'},
 {id:'BR-022',name:'Payroll finality',domain:'payroll-execution',invariant:'Batch submission does not mark employees paid; success or reversal is applied per employee and reconciled before final state.'},
 {id:'BR-023',name:'Financial account zero disclosure',domain:'banking-operations',invariant:'Unassigned accounts, balances, transactions, beneficiaries, payroll batches, reports and their derived counts are absent from every surface.'},
 {id:'BR-024',name:'Authoritative offboarding access removal',domain:'lifecycle',invariant:'A checklist cannot claim access removal, completion or not-applicable status without authoritative identity, session and company-scope verification; one-company exits preserve unrelated company access.'},
];

const n=(f:Record<string,string>,key:string)=>Number(f[key]||0);
export function purchaseCommitment(row:RecordData){return row.module==='purchase-orders'&&['Ordered','Partially Received'].includes(row.status)?Math.max(0,n(row.fields,'Quantity')-n(row.fields,'Received Quantity'))*n(row.fields,'Unit Cost'):0;}
export function bakeryBalance(fields:Record<string,string>){
 const produced=n(fields,'Actual Yield'),dispatched=n(fields,'Dispatched'),store=n(fields,'Store Balance');
 const assigned=['Agent Sold','Returns','Damaged','Promo','Staff','In Transit'].reduce((sum,key)=>sum+n(fields,key),0);
 const quantityVariance=produced-store-dispatched+dispatched-assigned-n(fields,'Resolution Quantity');
 const expectedRemittance=n(fields,'Agent Sold')*n(fields,'Unit Price');
 const cashVariance=expectedRemittance-n(fields,'Remittance')-n(fields,'Resolution Amount');
 return {produced,dispatched,store,assigned,quantityVariance,expectedRemittance,cashVariance,dispatchVariance:dispatched-assigned};
}
export function stockAvailability(row:RecordData){return Math.max(0,n(row.fields,'On Hand')-n(row.fields,'Reserved'));}
export function attendanceState(events:{kind:'in'|'out';time:string;success:boolean}[]){const good=events.filter(e=>e.success);const first=good.find(e=>e.kind==='in');const last=good.find(e=>e.kind==='out'&&!!first&&Date.parse(e.time)>Date.parse(first.time));return first&&last?'Present':first?'Incomplete':'Not Started';}
export function businessError(row:RecordData,fields:Record<string,string>,status:string):string|null {
 const f={...row.fields,...fields};const nums=['Quantity','Unit Cost','Received Quantity','Actual Yield','Dispatched','Store Balance','Agent Sold','Returns','Damaged','Promo','Staff','In Transit','Unit Price','Remittance','Resolution Quantity','Resolution Amount','Accepted Quantity','Rejected Quantity','Returned Quantity'];
 for(const key of nums)if(f[key]!==undefined&&f[key]!==''&&(!Number.isFinite(Number(f[key]))||Number(f[key])<0))return `${key} must be a valid nonnegative number.`;
 if(row.module==='expenses'&&['Submitted','Approved'].includes(status)&&(!Number.isFinite(n(f,'Amount'))||n(f,'Amount')<=0||!f.Purpose?.trim()))return 'A positive expense amount and business purpose are required.';
 if(row.module==='leave'&&['Submitted','Approved'].includes(status)&&(!f['Start Date']||!f['End Date']||f['Start Date']>f['End Date']))return 'Choose an ordered start and end date for leave.';
 if(row.module==='purchase-orders'){
  if(n(f,'Received Quantity')>n(f,'Quantity'))return 'Received quantity cannot exceed ordered quantity.';
  if(['Ordered','Partially Received','Received','Closed'].includes(status)&&n(f,'Quantity')<=0)return 'An order requires a positive quantity.';
  if(['Received','Closed'].includes(status)&&n(f,'Received Quantity')!==n(f,'Quantity'))return 'The full ordered quantity must be received before closure.';
 }
 if(row.module==='goods-receipts'&&['Accepted','Posted'].includes(status)&&n(f,'Accepted Quantity')+n(f,'Rejected Quantity')!==n(f,'Quantity'))return 'Accepted plus rejected quantity must equal delivered quantity.';
 if(row.module==='stock-transfers'&&['Received','Closed'].includes(status)&&n(f,'Received Quantity')!==n(f,'Quantity'))return 'Received quantity must equal transferred quantity.';
 if(row.module==='stock-transfers'&&f['From Location']===f['To Location']&&['Dispatched','In Transit','Received','Closed'].includes(status))return 'Transfer locations must be different.';
 if(row.module==='stock-borrowing'&&['Returned','Closed'].includes(status)&&n(f,'Returned Quantity')!==n(f,'Quantity'))return 'All borrowed stock must be returned before closure.';
 if(row.module==='bakery-accountability'&&['Resolved','Reconciled'].includes(status)){
  const b=bakeryBalance(f);if(b.quantityVariance!==0||b.cashVariance!==0||b.dispatchVariance!==0)return 'Unexplained loaf or remittance variance blocks reconciliation.';
  if((n(f,'Resolution Quantity')||n(f,'Resolution Amount'))&&(!f['Decision Reason']?.trim()||status==='Reconciled'&&row.status!=='Resolved'))return 'An investigated, reasoned resolution is required before reconciliation.';
 }
 if(row.module==='logistics'&&['Delivered','Closed'].includes(status)&&(!f['Proof of Delivery']?.trim()||!activeEvidence(row).length))return 'Attach proof of delivery before delivery or closure.';
 if(row.module==='payroll'&&['Review','Approved','Draft Export'].includes(status)){if(n(f,'Gross Pay')-n(f,'Deductions')!==n(f,'Net Pay')||f['Bank Validation']!=='Validated'||f['Statutory Configuration']!=='Validated'||!activeEvidence(row).length)return 'Resolve earnings, bank, statutory and evidence checks before payroll review.';}
 if(row.module==='printing'&&status==='Complete'&&(!f['QC Evidence']?.trim()||!activeEvidence(row).length))return 'Attach QC evidence before completing production.';
 if(row.module==='finance'&&status==='Posted'&&(!Number.isFinite(n(f,'Debit'))||!Number.isFinite(n(f,'Credit'))||n(f,'Debit')!==n(f,'Credit')||f['Period State']!=='Open'))return 'Journal must balance and belong to an open period.';
 if(row.module==='autos'&&['Sold','Delivered'].includes(status)&&(!f.Documentation?.trim()||/required|pending/i.test(f.Documentation)))return 'Verified vehicle documentation is required before ownership handoff.';
 if(row.module==='lifecycle'&&/offboard|exit|termination/i.test(`${row.title} ${f['Lifecycle Type']||''}`)&&status==='Complete')return 'Access removal requires authoritative identity, session and company-scope verification before completion.';
 return null;
}

export interface ConfigVersion {id:string;kind:string;name:string;target:string;version:number;state:'Draft'|'Validated'|'Simulated'|'Published'|'Rolled Back'|'Archived';scope:string;definition:Record<string,string>;history:{actor:string;action:string;time:string;reason:string}[];}
export function validateConfig(config:ConfigVersion,authorizedModules:string[]){const errors:string[]=[];
 if(config.scope!=='Company'&&!config.definition.assignee?.trim())errors.push('Assign the configuration audience before publication.');
 if(!config.name.trim())errors.push('A descriptive name is required.');
 if(!authorizedModules.includes(config.target))errors.push('Choose an available data source.');
 if(Object.values(config.definition).some(v=>/\b(select\s+.+from|drop\s+table|eval\s*\(|javascript:|<script|function\s*\(|=>)/i.test(v)))errors.push('Only governed declarative values are allowed.');
 if(Object.entries(config.definition).some(([k,v])=>/bypass|disable.*(approval|permission|evidence)|skip.*audit/i.test(k+' '+v)))errors.push('Protected business invariants cannot be disabled.');
 if(config.kind==='theme-builder')for(const key of ['primary','surface','text'])if(!/^#[0-9a-f]{6}$/i.test(config.definition[key]||''))errors.push(`${key} must be a six-digit hex color.`);
 if(config.kind==='theme-builder'&&['primary','surface','text'].every(k=>/^#[0-9a-f]{6}$/i.test(config.definition[k]||''))){
  if(colorContrast(config.definition.text,config.definition.surface)<4.5)errors.push('Text and surface must meet a 4.5:1 contrast ratio.');
  if(colorContrast('#ffffff',config.definition.primary)<4.5)errors.push('Primary actions must provide 4.5:1 contrast with their white labels.');
  if(colorContrast(config.definition.primary,config.definition.surface)<3)errors.push('Primary controls must remain distinct from the surface at 3:1 or better.');
 }
 return errors;
}
export function colorContrast(a:string,b:string){const luminance=(hex:string)=>{const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722};const x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
export function metricValue(rows:RecordData[],metric:string,required?:string){
 if(metric==='record-value')return rows.reduce((s,r)=>s+r.amount,0);
 if(metric==='purchase-commitment')return rows.reduce((s,r)=>s+purchaseCommitment(r),0);
 if(metric==='evidence-gaps')return rows.filter(r=>required?!r.fields[required]?.trim():!activeEvidence(r).length).length;
 if(metric==='bakery-quantity')return rows.filter(r=>r.module==='bakery-accountability').reduce((s,r)=>s+bakeryBalance(r.fields).quantityVariance,0);
 if(metric==='bakery-cash')return rows.filter(r=>r.module==='bakery-accountability').reduce((s,r)=>s+bakeryBalance(r.fields).cashVariance,0);
 return rows.length;
}
export function safeCsvCell(value:unknown){const str=String(value??'');return '"'+(/^[\s]*[=+@\-\t\r]/.test(str)?"'"+str:str).replaceAll('"','""')+'"';}
export const metricCatalog=[
 {id:'record-count',name:'Authorized record count',unit:'records',formula:'count(authorized rows)'},
 {id:'record-value',name:'Authorized record value',unit:'NGN',formula:'sum(authorized record amount)'},
 {id:'evidence-gaps',name:'Evidence gaps',unit:'records',formula:'count(required field is empty)'},
 {id:'purchase-commitment',name:'Active purchase commitment',unit:'NGN',formula:'sum((ordered quantity − received quantity) × unit cost), ordered/partial only'},
 {id:'bakery-quantity',name:'Unexplained loaf variance',unit:'loaves',formula:'actual yield − store balance − disposition quantities − approved resolution'},
 {id:'bakery-cash',name:'Unexplained remittance variance',unit:'NGN',formula:'agent sold × unit price − remittance − approved resolution'},
];
